 import { db } from '../db';
 import { sql } from 'drizzle-orm';

+export async function funilPorCorretor(mes: string) {
+  // o builder não expressa count(*) FILTER (WHERE …); SQL cru de propósito
+  const r = await db.execute(sql`
+    SELECT corretor_id,
+           count(*) FILTER (WHERE etapa = 'visita') AS visitas,
+           count(*) FILTER (WHERE etapa = 'proposta') AS propostas
+    FROM leads
+    WHERE to_char(criado_em, 'YYYY-MM') = ${mes}
+    GROUP BY corretor_id`);
+  return r.rows;
+}

