+/**
+ * @description Lista telefones com mais de um lead, para a fila de deduplicação.
+ */
+export async function telefonesDuplicados() {
+  /*
+   * DISTINCT ON + HAVING com janela não sai do builder sem gambiarra;
+   * SQL cru revisado com o DBA em 2026-09-20.
+   */
+  const r = await db.execute(sql`
+    SELECT telefone, count(*) AS n FROM leads
+    GROUP BY telefone HAVING count(*) > 1 ORDER BY n DESC`);
+  return r.rows;
+}

