new file mode 100644
--- /dev/null
+++ b/src/util/telefone.ts
@@ -0,0 +1,13 @@
+const SO_DIGITOS = /\D/g;
+
+function limpar(s: string): string {
+  return s.replace(SO_DIGITOS, '');
+}
+
+/**
+ * @description Normaliza telefone brasileiro para E.164 (+55DDDNÚMERO).
+ */
+export const normalizarTelefone = (bruto: string): string => {
+  const d = limpar(bruto);
+  return d.startsWith('55') ? `+${d}` : `+55${d}`;
+};

